import{_ as o,a0 as p,w as r,s as d,ao as l,I as a,x as e,a1 as s,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 CentOS、RHEL、Rocky Linux 最小化安装中设置互联网 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS、RHEL、Rocky Linux 最小化安装中设置互联网 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS、RHEL、Rocky Linux 最小化安装中设置互联网 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS、RHEL、Rocky Linux 最小化安装中设置互联网 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210625 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install","title":"如何在 CentOS、RHEL、Rocky Linux 最小化安装中设置互联网","tag":"202107","desc":""},"relativePath":"202107/20210625 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install.md","filePath":"[post].md"}'),u={name:"202107/20210625 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install.md"};function g(k,t,h,c,m,b){const i=p("Link");return r(),d("div",null,[t[23]||(t[23]=l('<h1 id="如何在-centos、rhel、rocky-linux-最小化安装中设置互联网" tabindex="-1">如何在 CentOS、RHEL、Rocky Linux 最小化安装中设置互联网 <a class="header-anchor" href="#如何在-centos、rhel、rocky-linux-最小化安装中设置互联网" aria-label="Permalink to “如何在 CentOS、RHEL、Rocky Linux 最小化安装中设置互联网”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202107/16/104745wne0x111onmafxj9.jpg" alt=""></p><p>在最小化服务器安装中，设置互联网或网络是非常容易的。在本指南中，我们将解释如何在 CentOS、RHEL、Rocky Linux 最小安装中设置互联网或网络。</p><p>当你刚刚完成任何服务器发行版的最小化安装时，你没有任何图形界面或桌面环境可以用于设置你的网络或互联网。因此，当你只能使用终端时，了解如何设置联网是很重要的。NetworkManager 以及 systemd 服务为完成这项工作提供了必要的工具。以下是具体使用方法。</p><h3 id="在-centos、rhel、rocky-linux-最小化安装中设置互联网" tabindex="-1">在 CentOS、RHEL、Rocky Linux 最小化安装中设置互联网 <a class="header-anchor" href="#在-centos、rhel、rocky-linux-最小化安装中设置互联网" aria-label="Permalink to “在 CentOS、RHEL、Rocky Linux 最小化安装中设置互联网”">​</a></h3><p>完成安装后，启动服务器终端。理想情况下，你应该会看到提示符。使用 root 或 admin 账户登录。</p><p>然后，首先尝试使用 <code>nmcli</code> 检查网络接口的状态和细节。<code>nmcli</code> 是一个控制 NetworkManager 服务的命令行工具。使用以下命令进行检查。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmcli device status</span></span></code></pre></div><p>这将显示设备名称、状态等。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/nmcli-device-status.jpg" alt="nmcli device status"></p>',10)),a("p",null,[t[1]||(t[1]=e("运行工具 ",-1)),t[2]||(t[2]=a("code",null,"nmtui",-1)),t[3]||(t[3]=e(" 来配置网络接口。",-1)),s(i,{href:"https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/7/html/networking_guide/sec-configuring_ip_networking_with_nmtui"},{default:n(()=>[...t[0]||(t[0]=[e("nmtui",-1)])]),_:1}),t[4]||(t[4]=e(" 是 NetworkManager 工具的一部分，它为你提供了一个漂亮的用户界面来配置网络。这是 NetworkManager-tui 包的一部分，当你完成最小服务器的安装时它应该默认安装。",-1))]),t[24]||(t[24]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmtui</span></span></code></pre></div><p>在 <code>nmtui</code> 窗口中点击编辑一个连接。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/nmtui-Select-options.jpg" alt="nmtui – Select options"></p><p>选择网口名称：</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Select-Interface-to-Edit.jpg" alt="Select Interface to Edit"></p><p>在编辑连接窗口，为 IPv4 和 IPv6 选择自动。并选择自动连接。完成后按 “OK”。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/nmtui-Edit-Connection.jpg" alt="nmtui – Edit Connection"></p>',7)),a("p",null,[t[6]||(t[6]=e("通过使用如下 ",-1)),s(i,{href:"https://www.debugpoint.com/2020/12/systemd-systemctl-service/"},{default:n(()=>[...t[5]||(t[5]=[e("systemd systemctl",-1)])]),_:1}),t[7]||(t[7]=e(" 命令，重新启动 NetworkManager 服务。",-1))]),t[25]||(t[25]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart NetworkManager</span></span></code></pre></div><p>如果一切顺利，在 CentOS、RHEL、Rocky Linux 服务器的最小化安装中你应该可以连接到网络和互联网了，前提是你的网络有互联网连接。你可以用 <code>ping</code> 来验证它是否正常。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/setup-internet-minimal-server-CentOS-Rocky-Linux-RHEL.jpg" alt="setup internet minimal server – CentOS Rocky Linux RHEL"></p><h3 id="额外技巧-在最小化服务器中设置静态-ip" tabindex="-1">额外技巧：在最小化服务器中设置静态 IP <a class="header-anchor" href="#额外技巧-在最小化服务器中设置静态-ip" aria-label="Permalink to “额外技巧：在最小化服务器中设置静态 IP”">​</a></h3><p>当你把网络配置设置为自动，当你连接到互联网时，网口会动态地分配 IP。在某些情况下，当你建立一个局域网 （LAN） 时，你可能想给你的网口分配静态 IP。这超级简单。</p><p>打开你的网络的网络配置脚本。根据你的设备修改高亮部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/sysconfig/network-scripts/ifcfg-ens3</span></span></code></pre></div><p>在上面的文件中，用 <code>IPADDR</code> 属性添加你想要的 IP 地址。保存该文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IPADDR=192.168.0.55</span></span></code></pre></div><p>在 <code>/etc/sysconfig/network</code> 中为你的网络添加网关：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NETWORKING=yes</span></span>
<span class="line"><span>HOSTNAME=debugpoint</span></span>
<span class="line"><span>GATEWAY=10.1.1.1</span></span></code></pre></div><p>在 <code>/etc/resolv.conf</code> 的 <code>resolv.conf</code> 中添加任意公共 DNS 服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 8.8.8.8</span></span>
<span class="line"><span>nameserver 8.8.4.4</span></span></code></pre></div><p>并重新启动网络服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart NetworkManager</span></span></code></pre></div><p>这样就完成了静态 IP 的设置。你也可以使用 <code>ip addr</code> 命令检查详细的 IP 信息。</p><p>我希望这个指南能帮助你在你的最小化服务器中设置网络、互联网和静态 IP。如果你有任何问题，请在评论区告诉我。</p><hr>`,18)),a("p",null,[t[9]||(t[9]=e("via: ",-1)),s(i,{href:"https://www.debugpoint.com/2021/06/setup-internet-minimal-install-server/"},{default:n(()=>[...t[8]||(t[8]=[e("https://www.debugpoint.com/2021/06/setup-internet-minimal-install-server/",-1)])]),_:1})]),a("p",null,[t[14]||(t[14]=e("作者：",-1)),s(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...t[10]||(t[10]=[e("Arindam",-1)])]),_:1}),t[15]||(t[15]=e(" 选题：",-1)),s(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[11]||(t[11]=[e("lujun9972",-1)])]),_:1}),t[16]||(t[16]=e(" 译者：",-1)),s(i,{href:"https://github.com/geekpi"},{default:n(()=>[...t[12]||(t[12]=[e("geekpi",-1)])]),_:1}),t[17]||(t[17]=e(" 校对：",-1)),s(i,{href:"https://github.com/turbokernel"},{default:n(()=>[...t[13]||(t[13]=[e("turbokernel",-1)])]),_:1})]),a("p",null,[t[20]||(t[20]=e("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原创编译，",-1)),s(i,{href:"https://linux.cn/"},{default:n(()=>[...t[19]||(t[19]=[e("Linux中国",-1)])]),_:1}),t[22]||(t[22]=e(" 荣誉推出",-1))])])}const w=o(u,[["render",g]]);export{C as __pageData,w as default};
